// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address actor, uint256 firstDeposit, uint256 secondDeposit) public {
        vm.assume(actor != address(0));
        firstDeposit = bound(firstDeposit, 0, 1 ether);
        secondDeposit = bound(secondDeposit, 0, 1 ether);

        vm.deal(actor, firstDeposit + secondDeposit + 1);

        vm.prank(actor);
        c.addToBalance{value: firstDeposit}();

        uint256 pre = c.getBalance(actor);

        vm.prank(actor);
        c.addToBalance{value: secondDeposit}();

        uint256 post = c.getBalance(actor);
        assertTrue(post == pre + secondDeposit);
    }
}
